fn fold(&self, expr: Expression) -> Result<Expression> {
    use Expression::*;

    Ok(match expr {
        And(l, r) => {
            let l = self.fold(*l)?;
            let r = self.fold(*r)?;
            match (l.evaluate(None)?, r.evaluate(None)?) {
                (Value::Boolean(true), Value::Boolean(true)) => Value::Boolean(true).into(),
                (Value::Boolean(false), _) => Value::Boolean(false).into(),
                (_, Value::Boolean(false)) => Value::Boolean(false).into(),
                (Value::Boolean(l), Value::Boolean(r)) => Value::Boolean(l && r).into(),
                _ => And(l.into(), r.into()),
            }
        }
        Or(l, r) => {
            let l = self.fold(*l)?;
            let r = self.fold(*r)?;
            match (l.evaluate(None)?, r.evaluate(None)?) {
                (Value::Boolean(true), _) => Value::Boolean(true).into(),
                (_, Value::Boolean(true)) => Value::Boolean(true).into(),
                (Value::Boolean(false), Value::Boolean(false)) => Value::Boolean(false).into(),
                (Value::Boolean(l), Value::Boolean(r)) => Value::Boolean(l || r).into(),
                _ => Or(l.into(), r.into()),
            }
        }
        Equal(l, r) => {
            let l = self.fold(*l)?;
            let r = self.fold(*r)?;
            match (l.evaluate(None)?, r.evaluate(None)?) {
                (l, r) if l == r => Value::Boolean(true).into(),
                (l, r) => Equal(l.into(), r.into()),
            }
        }
        NotEqual(l, r) => {
            let l = self.fold(*l)?;
            let r = self.fold(*r)?;
            match (l.evaluate(None)?, r.evaluate(None)?) {
                (l, r) if l != r => Value::Boolean(true).into(),
                (l, r) => NotEqual(l.into(), r.into()),
            }
        }
        GreaterThan(l, r) => {
            let l = self.fold(*l)?;
            let r = self.fold(*r)?;
            match (l.evaluate(None)?, r.evaluate(None)?) {
                (Value::Integer(l), Value::Integer(r)) => Value::Boolean(l > r).into(),
                (Value::Integer(l), Value::Float(r)) => Value::Boolean((l as f64) > r).into(),
                (Value::Float(l), Value::Integer(r)) => Value::Boolean(l > (r as f64)).into(),
                (Value::Float(l), Value::Float(r)) => Value::Boolean(l > r).into(),
                (l, r) => GreaterThan(l.into(), r.into()),
            }
        }
        GreaterThanOrEqual(l, r) => {
            let l = self.fold(*l)?;
            let r = self.fold(*r)?;
            match (l.evaluate(None)?, r.evaluate(None)?) {
                (Value::Integer(l), Value::Integer(r)) => Value::Boolean(l >= r).into(),
                (Value::Integer(l), Value::Float(r)) => Value::Boolean((l as f64) >= r).into(),
                (Value::Float(l), Value::Integer(r)) => Value::Boolean(l >= (r as f64)).into(),
                (Value::Float(l), Value::Float(r)) => Value::Boolean(l >= r).into(),
                (l, r) => GreaterThanOrEqual(l.into(), r.into()),
            }
        }
        LessThan(l, r) => {
            let l = self.fold(*l)?;
            let r = self.fold(*r)?;
            match (l.evaluate(None)?, r.evaluate(None)?) {
                (Value::Integer(l), Value::Integer(r)) => Value::Boolean(l < r).into(),
                (Value::Integer(l), Value::Float(r)) => Value::Boolean((l as f64) < r).into(),
                (Value::Float(l), Value::Integer(r)) => Value::Boolean(l < (r as f64)).into(),
                (Value::Float(l), Value::Float(r)) => Value::Boolean(l < r).into(),
                (l, r) => LessThan(l.into(), r.into()),
            }
        }
